import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.Cvf4Fkn6.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1794574960000}'),l={name:"guide/faq.md"};function i(n,a,d,s,h,c){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="拖动窗口时布局图标条没有出现" tabindex="-1">拖动窗口时布局图标条没有出现？ <a class="header-anchor" href="#拖动窗口时布局图标条没有出现" aria-label="Permalink to &quot;拖动窗口时布局图标条没有出现？&quot;">​</a></h2><p>按顺序检查：</p><ol><li><strong>辅助功能授权</strong>：菜单栏图标若为 ⚠️ 闪烁状态说明缺权限，去 <strong>系统设置 → 隐私与安全性 → 辅助功能</strong> 授权（或设置「行为」页点「去授权」）</li><li><strong>⌥ 键模式</strong>：设置「行为」页若选了「按住 ⌥ 显示布局图标」，普通拖动不会显示，需按住 ⌥</li><li><strong>菜单栏状态图标</strong>被关闭时，图标条仍会正常出现——此项只影响菜单栏</li><li>仍不工作请查日志：设置「关于」页点「打开日志」，或直接看 <code>~/Library/Logs/WTidy.log</code></li></ol><h2 id="重新安装-更新后又要重新授权" tabindex="-1">重新安装 / 更新后又要重新授权？ <a class="header-anchor" href="#重新安装-更新后又要重新授权" aria-label="Permalink to &quot;重新安装 / 更新后又要重新授权？&quot;">​</a></h2><p>WTidy 为 ad-hoc 签名，每次构建签名都不同，macOS 将其视为新应用。在辅助功能列表中<strong>先移除旧条目，再重新添加</strong>即可。</p><h2 id="与-macos-自带的分屏冲突吗" tabindex="-1">与 macOS 自带的分屏冲突吗？ <a class="header-anchor" href="#与-macos-自带的分屏冲突吗" aria-label="Permalink to &quot;与 macOS 自带的分屏冲突吗？&quot;">​</a></h2><p>可共存：WTidy 由顶部布局图标条触发，macOS 15+ 原生磁贴由窗口拖到屏幕边缘触发，入口不同。嫌干扰可在 <strong>系统设置 → 桌面与程序坞</strong> 关闭「将窗口拖到屏幕边缘时平铺」。</p><h2 id="某个应用拖动没有反应" tabindex="-1">某个应用拖动没有反应？ <a class="header-anchor" href="#某个应用拖动没有反应" aria-label="Permalink to &quot;某个应用拖动没有反应？&quot;">​</a></h2><p>部分 Java / Electron 应用不发出拖拽通知，拖拽分屏对它们无效。用快捷键兜底：<code>⌥⌘←</code> / <code>⌥⌘→</code> 等<a href="./hotkeys.html#内置快捷键">内置快捷键</a>，或为常用区域<a href="./hotkeys.html#改录与自定义">改录自己的组合</a>。</p><h2 id="多显示器如何工作" tabindex="-1">多显示器如何工作？ <a class="header-anchor" href="#多显示器如何工作" aria-label="Permalink to &quot;多显示器如何工作？&quot;">​</a></h2><ul><li>布局可设<strong>作用域</strong>：所有屏幕，或仅指定显示器（如三等分只在超宽屏出现）</li><li>拖到哪块屏，图标条就出现在哪块屏，按该屏的可用布局工作</li><li>菜单栏「发送窗口到另一块屏幕」把前台窗口发往它不在的那块屏（多屏时以鼠标所在屏为目标）</li></ul><h2 id="如何开机自启" tabindex="-1">如何开机自启？ <a class="header-anchor" href="#如何开机自启" aria-label="Permalink to &quot;如何开机自启？&quot;">​</a></h2><p>设置窗口底部的「开机自动启动」开关（SMAppService 实现，重启后稳定生效）。</p><h2 id="如何彻底卸载" tabindex="-1">如何彻底卸载？ <a class="header-anchor" href="#如何彻底卸载" aria-label="Permalink to &quot;如何彻底卸载？&quot;">​</a></h2><ol><li>菜单栏图标 → 退出 WTidy</li><li>把 <code>WTidy.app</code> 移到废纸篓（登录项由系统随应用移除自动清理）</li><li>残留数据（可选清理）：偏好 <code>~/Library/Preferences/com.allblue.wtidy.plist</code>、日志 <code>~/Library/Logs/WTidy.log</code></li></ol><h2 id="支持-intel-mac-吗" tabindex="-1">支持 Intel Mac 吗？ <a class="header-anchor" href="#支持-intel-mac-吗" aria-label="Permalink to &quot;支持 Intel Mac 吗？&quot;">​</a></h2><p>官方发布的包为 <strong>Apple Silicon（arm64）原生构建</strong>，不依赖 Rosetta 2。Intel 机器可自行源码构建——<code>swift build</code> 默认按本机架构编译，详见<a href="./getting-started.html#_5-从源码构建-进阶">从源码构建</a>。</p><h2 id="快捷键按下没反应" tabindex="-1">快捷键按下没反应？ <a class="header-anchor" href="#快捷键按下没反应" aria-label="Permalink to &quot;快捷键按下没反应？&quot;">​</a></h2><p>组合可能被其他应用的全局快捷键占用（输入法、截图工具等），换一组或在录制时看冲突提示（会显示占用者名称）。见<a href="./hotkeys.html#冲突拦截">快捷键 · 冲突拦截</a>。</p>',20)])])}const u=e(l,[["render",i]]);export{p as __pageData,u as default};
